            app.stop();
            databaseConfig.close();
        }));

        System.out.println("Pousada Maré Alta - Sistema de Reservas iniciado na porta " + port);
    }

    private static Connection getConnection(DatabaseConfig config) {
        try {
            return config.getConnection();
        } catch (Exception e) {
