            if (e instanceof InvalidRequestException || e instanceof RoomNotFoundException ||
                e instanceof RoomUnavailableException || e instanceof CapacityExceededException) {
                throw e;
            }
            throw new RuntimeException("Erro ao processar requisição", e);
        }
