package br.com.pousadamarealta;

import br.com.pousadamarealta.infrastructure.database.DatabaseConfig;
import br.com.pousadamarealta.infrastructure.database.DatabaseInitializer;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.Connection;

import static org.assertj.core.api.Assertions.assertThat;

@Testcontainers
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class IntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18")
        .withDatabaseName("test")
        .withUsername("test")
        .withPassword("test");

    static DatabaseConfig databaseConfig;
    static io.javalin.Javalin app;
    static HttpClient httpClient = HttpClient.newHttpClient();
    static final int PORT = 7171;

    @BeforeAll
    static void setup() throws Exception {
        databaseConfig = new DatabaseConfig(
            postgres.getJdbcUrl(),
            postgres.getUsername(),
            postgres.getPassword()
        );

        try (Connection connection = databaseConfig.getConnection()) {
            DatabaseInitializer.initialize(connection);
        }

        startApp();
        Thread.sleep(1000);
    }

    @AfterAll
    static void teardown() {
        if (app != null) {
            app.stop();
